export function lineChart(series,{width=600,height=240,min=0,max,labels=['Start','End'],cursor=null}={}){const values=series.flatMap(s=>s.values),length=Math.max(...series.map(s=>s.values.length));max=max??Math.max(1,...values);if(max<=min)max=min+1;const left=42,right=15,top=18,bottom=30,x=(i,len)=>left+i/Math.max(1,length-1)*(width-left-right),y=v=>height-bottom-(v-min)/(max-min)*(height-top-bottom);let out=`<svg viewBox="0 0 ${width} ${height}" aria-hidden="true">`;for(let k=0;k<=4;k++){const value=min+(max-min)*k/4;out+=`<line x1="${left}" x2="${width-right}" y1="${y(value)}" y2="${y(value)}" stroke="var(--line)"/><text x="${left-8}" y="${y(value)+4}" text-anchor="end">${Number(value.toFixed(1))}</text>`;}for(const s of series)out+=`<path d="${s.values.map((v,i)=>`${i?'L':'M'}${x(i,s.values.length)},${y(v)}`).join(' ')}" fill="none" stroke="${s.color||'var(--accent)'}" stroke-width="2.5" ${s.dashed?'stroke-dasharray="5 4"':''}/>`;if(cursor!==null)out+=`<line x1="${x(cursor,series[0].values.length)}" x2="${x(cursor,series[0].values.length)}" y1="${top}" y2="${height-bottom}" stroke="var(--line-strong)"/>`;return out+`<text x="${left}" y="${height-6}">${labels[0]}</text><text x="${width-right}" y="${height-6}" text-anchor="end">${labels[1]}</text></svg>`;}
